import{_ as a,a as r,b as e}from"./chunks/17-chat-lorebook-select.D4wd7hLI.js";import{_ as o,o as i,c as n,a2 as l}from"./chunks/framework.z3u3TMv0.js";const g=JSON.parse('{"title":"ワールドブック","description":"MiniTavern ワールドブック（Lorebook）：グローバル庫、セッション紐付け、キーワード触発注入；長編 AI ロールプレイの設定を安定させる。","frontmatter":{"title":"ワールドブック","description":"MiniTavern ワールドブック（Lorebook）：グローバル庫、セッション紐付け、キーワード触発注入；長編 AI ロールプレイの設定を安定させる。","head":[["meta",{"name":"keywords","content":"酒場,AI酒場,MiniTavern,AI相棒,AI友達,AIローカルチャット,Silly Tavern,SillyTavern,スマホでSilly Tavern,Silly Tavernスマホ版,Silly Tavern Android,Silly Tavern iOS,AIロールプレイ,キャラクターカード,AIチャット,スマホAI,オフラインAI,AIストーリー,ローカルLLM,Ollama,LM Studio,ワールドブック,正規表現,BYOK,ユーザーガイド,マニュアル"}],["meta",{"property":"og:title","content":"ワールドブック · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern ワールドブック（Lorebook）：グローバル庫、セッション紐付け、キーワード触発注入；長編 AI ロールプレイの設定を安定させる。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ja/manual/lorebook"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ja/manual/lorebook"}]]},"headers":[],"relativePath":"ja/manual/lorebook.md","filePath":"ja/manual/lorebook.md","lastUpdated":1787224147000}'),d={name:"ja/manual/lorebook.md"};function s(h,t,p,c,m,u){return i(),n("div",null,[...t[0]||(t[0]=[l('<h1 id="ワールドブック" tabindex="-1">ワールドブック <a class="header-anchor" href="#ワールドブック" aria-label="Permalink to &quot;ワールドブック&quot;">​</a></h1><p>経路：<strong>設定 → ワールドブック</strong>；セッション紐付けは <strong>チャット設定 → ワールドブック</strong>。</p><h2 id="グローバル庫" tabindex="-1">グローバル庫 <a class="header-anchor" href="#グローバル庫" aria-label="Permalink to &quot;グローバル庫&quot;">​</a></h2><p><img src="'+a+'" alt="ワールドブック一覧"></p><ol><li>ワールドブックを新規作成または取り込み。</li><li>書内で<strong>条目</strong>を管理（キーワード、常駐、確率、深さなど）。</li><li>書き出し、複製、ピン留め、検索、削除が可能。</li></ol><p><img src="'+r+'" alt="条目編集"></p><h3 id="条目の概念-要約" tabindex="-1">条目の概念（要約） <a class="header-anchor" href="#条目の概念-要約" aria-label="Permalink to &quot;条目の概念（要約）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>概念</th><th>意味</th></tr></thead><tbody><tr><td>常駐</td><td>キーワードに依存せず、予算内で注入</td></tr><tr><td>キーワード</td><td>直近対話をスキャンし、一致したら注入</td></tr><tr><td>確率</td><td>ヒット後、確率で注入するかを決める</td></tr><tr><td>スキャン深さ / token 予算</td><td>スキャン範囲と注入長を制御</td></tr><tr><td>@Depth など</td><td>対話の特定位置へ挿入（上級）</td></tr></tbody></table><h2 id="セッション紐付け" tabindex="-1">セッション紐付け <a class="header-anchor" href="#セッション紐付け" aria-label="Permalink to &quot;セッション紐付け&quot;">​</a></h2><p>経路：対話 → 設定 → <strong>ワールドブック</strong></p><p><img src="'+e+'" alt="セッションのワールドブック"></p><ul><li>グローバル書を<strong>複数選択</strong>；選んだ時点で本聊の設定に書き込み。</li><li><strong>空選択＝どのワールドブックも注入しない</strong>（カード内書を含む；製品の現行ロジック準拠）。</li><li>キャラから新規チャットするとき、カードに紐づくワールドブック ID をコピーすることが多い。</li></ul><h2 id="キャラカードとの関係" tabindex="-1">キャラカードとの関係 <a class="header-anchor" href="#キャラカードとの関係" aria-label="Permalink to &quot;キャラカードとの関係&quot;">​</a></h2><p>ワールドブック付きカードを取り込むとき：カード内に一份残し（書き出し用）、グローバルへコピーしてチャット紐付けにも使えます。キャラ削除時、「そのカードに属する」ワールドブックを消すか選べます。</p>',14)])])}const k=o(d,[["render",s]]);export{g as __pageData,k as default};
